  it.todo("should return empty grid for an empty grid -- []");
  it.todo("should kill a single cell (0 neighbors) -- [(0,0)] -> []");
  it.todo("should kill live cells with only 1 neighbor (underpopulation) -- [(0,1),(1,1)] -> []");
  it.todo("should preserve a live cell with 2 or 3 live neighbors (survival) -- center (1,1) in ###/.#. survives");
  it.todo("should kill a live cell with more than 3 live neighbors (overpopulation) -- center (1,1) with 4 neighbors dies");
  it.todo("should birth a dead cell with exactly 3 live neighbors (reproduction) -- (1,1) in ##./#.. becomes alive");
  it.todo("should reproduce a blinker oscillator Gen 0 to Gen 1 -- [(0,0),(0,1),(0,2)] -> [(-1,1),(0,1),(1,1)]");
  it.todo("should keep a block still life unchanged -- [(0,0),(1,0),(0,1),(1,1)] -> same coordinates");
});

