export type Cell = [number, number];

const key = (x: number, y: number): string => `${x},${y}`;

export function nextGeneration(cells: Cell[]): Cell[] {
  const live = new Set(cells.map(([x, y]) => key(x, y)));
  const neighborCounts = new Map<string, number>();

  for (const [x, y] of cells) {
    for (let dx = -1; dx <= 1; dx++) {
      for (let dy = -1; dy <= 1; dy++) {
        if (dx === 0 && dy === 0) continue;
        const position = key(x + dx, y + dy);
        neighborCounts.set(position, (neighborCounts.get(position) ?? 0) + 1);
      }
    }
  }

  const next: Cell[] = [];
  for (const [position, count] of neighborCounts) {
    const isAlive = live.has(position);
    if (count === 3 || (isAlive && count === 2)) {
      const [x, y] = position.split(",").map(Number);
      next.push([x, y]);
    }
  }

  return next.sort((a, b) => a[0] - b[0] || a[1] - b[1]);
}

